modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.Comparator;
end Baseline;
model FINDING00780
  extends Modelica.Electrical.Analog.Examples.OpAmps.Comparator(f=0);
end FINDING00780;
model FINDING00781
  extends Modelica.Electrical.Analog.Examples.OpAmps.Comparator(Vps=-15);
end FINDING00781;
model FinalFINDING00780
  extends Modelica.Electrical.Analog.Examples.OpAmps.Comparator(final f=0);
end FinalFINDING00780;
model FinalFINDING00781
  extends Modelica.Electrical.Analog.Examples.OpAmps.Comparator(final Vps=-15);
end FinalFINDING00781;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00780\n");
simulate(FINDING00780, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00781\n");
simulate(FINDING00781, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00780\n");
simulate(FinalFINDING00780, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00781\n");
simulate(FinalFINDING00781, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00780\n");
system("./Baseline -override f=0 -r=FINDING00780_override.csv");
print("AUDIT_OVERRIDE FINDING00781\n");
system("./Baseline -override Vps=-15 -r=FINDING00781_override.csv");
